            mistake: 'Stocker les prompts dans Slack, les emails ou des notes personnelles',
            problem: 'Aucun historique de versions, aucun accès partagé, impossible d\'auditer ce qui a changé quand quelque chose se casse en production',
            fix: 'Migrer en fichiers YAML dans un dépôt Git partagé au Jour 2 du setup. Même un fichier plat unique est mieux qu\'un fil Slack.',
