            problem: 'Crée un point de défaillance unique — cette personne devient un goulot d\'étranglement et les prompts vieillissent quand elle est indisponible',
            fix: 'Attribuer la propriété par cas d\'usage ou zone produit, pas par personne. Répartir 2–3 owners sur les zones fonctionnelles est le bon modèle.',
