        title: 'Questions fréquemment posées',
        content: '**Les questions les plus fréquentes des petites équipes portent sur le setup minimum viable, Git vs outils dédiés, le choix de modèle et la prévention des régressions silencieuses.** Chaque réponse inclut un seuil concret ou une action.',
