          '**3일차 — 가장 중요한 프롬프트 3개를 YAML 파일로 이전.** 전체 메타데이터 템플릿으로 작성하십시오. `feat(prompts): migrate summarise-for-pm to library v1.0.0`과 같은 메시지로 공유 저장소에 커밋하십시오. 이 3개 파일이 라이브러리의 기반입니다.',
