          '**5일차 — 최소 2개 모델에서 테스트 세트 실행.** PromptQuorum 또는 자체 API 호출을 사용하여 GPT-5.5와 Claude 4.6 Sonnet에서 20개 케이스를 실행하십시오. 각 모델의 합격률을 기록하십시오. 이 기준선이 팀이 추적할 가장 중요한 수치입니다. 향후 모든 프롬프트 변경은 이 기준선과 같거나 더 높은 점수를 받아야 합니다.',
